files.templates/lead-intake-qualifier/TEMPLATE:
{
  "schema_version": 1,
  "template_id": "lead-intake-qualifier",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the sales role",
      "instructions": "Confirm whether Lead Intake & Qualifier is the primary Crew role or a supporting capability. Preserve an existing Crew identity and record the named business owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/lead-intake-qualifier/SKILL.md exists and lead-intake-qualifier is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set business and lead scope",
      "instructions": "Confirm the offer, target buyer, market, reporting window, and authorized source scope for this role. Minimum input: A real inbound enquiry or export, ideal-customer criteria, territory or routing rules, and a lead owner."
    },
    {
      "id": "access",
      "title": "Test source access",
      "instructions": "Read a representative authorized source or export. HubSpot, Salesforce, another approved CRM, form inbox, or a supplied export. A file is enough for the first review. Record the actual account or file, date coverage, and missing access; a named provider is not a connected account."
    },
    {
      "id": "policy",
      "title": "Verify source and decision rules",
      "instructions": "For one inbound enquiry, resolve the exact source row, company/domain, lead and contact references, approved fit-policy version and owner. Check duplicates across the authorized CRM scope and current contact/suppression state. Reproduce one criterion from source evidence; keep missing data unknown and have the owner approve the qualification and route before any CRM write or contact."
    },
    {
      "id": "first_result",
      "title": "Produce the first result",
      "instructions": "Produce A lead qualification brief with fit reasons, source references, missing details, and a proposed owner. Each brief cites the original enquiry or export row, qualification policy, checked duplicate scope, and the source of every fit claim. Use actual authorized data; a fictional example alone does not complete this check."
    },
    {
      "id": "review",
      "title": "Review the first result",
      "instructions": "Show a representative output to the owner and record corrections, decision, and next action before completing setup."
    },
    {
      "id": "delivery",
      "title": "Decide on delivery",
      "optional": true,
      "instructions": "Choose chat-only or a separately approved CRM/email/calendar route. Chat-only is a completed decision. No outbound action or CRM mutation is enabled by this template."
    },
    {
      "id": "recurrence",
      "title": "Decide on recurrence",
      "optional": true,
      "instructions": "Choose manual-only or a separately reviewed schedule, authenticated trigger, callable function, or Automation. Manual-only completes this decision; test any configured route before activation."
    }
  ],
  "completed_steps": []
}

