  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm Crew role and owner",
      "instructions": "Confirm whether Sales Call Briefing Assistant is the Crew’s primary role or a supporting capability. Preserve existing identity and name the accountable owner."
    },
    {
      "id": "skill",
      "title": "Verify selected skill",
      "instructions": "Confirm skills/sales-call-briefing/SKILL.md exists and sales-call-briefing is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Bind exact sales scope",
      "instructions": "Record business, source account, opportunity or meeting, offer, currency/timezone, first job and source versions. Minimum input: Meeting or opportunity ID, company identity, approved CRM notes and offer material, seller, meeting time, and source freshness rule."
    },
    {
      "id": "access",
      "title": "Probe authorized sources",
      "instructions": "Read one representative current source or export and record IDs, observation time and gaps. Calendar and CRM through scoped MCPs or supplied exports; public account research is optional and does not imply permission to contact."
    },
    {
      "id": "policy",
      "title": "Confirm claim and action policy",
      "instructions": "Record approved claims, pricing or stage definitions as applicable, owner approval, recipient/contact rules, and duplicate key. No calendar change, CRM write, customer contact, recording access or promise about product behavior is authorized by this template."
    },
    {
      "id": "first_result",
      "title": "Produce a sourced first result",
      "instructions": "Produce A meeting brief with exact attendee and meeting references, approved account facts, open questions, relevant product proof, and a seller review decision. Every claimed fact cites a meeting, CRM, approved product or public source ID and observation time; questions are labeled as questions. A fictional example does not complete setup."
    },
    {
      "id": "review",
      "title": "Review with sales owner",
      "instructions": "Show the real result, source coverage, calculations, unknowns and proposed next step. Record owner corrections or explicit decision."
    },
    {
      "id": "delivery",
      "title": "Choose chat-only or an action route",
      "optional": true,
      "instructions": "Chat-only completes this choice. Any send, CRM change or calendar action needs a separately approved exact-object route and provider receipt."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring work",
      "optional": true,
      "instructions": "Manual-only completes this choice. A schedule or authenticated event needs reviewed scope, deduplication, retries, cost and notification rules. Re-read the exact meeting and opportunity before each call; keep meeting ID and notes revision, report changed attendees/stage/commitments, and retire the brief when the meeting is cancelled."
    }
  ],
  "completed_steps": []
}

